async function submitAsn(event) {
  event.preventDefault(); const form = new FormData(event.currentTarget); const rows = [...$('#asnLines').children]; const sourcePurchaseOrders = [...new Set(rows.map((row) => row.dataset.purchaseOrder))];
  const items = rows.map((row) => ({ sourcePurchaseOrder: row.dataset.purchaseOrder, sourcePurchaseOrderItem: row.dataset.purchaseOrderItem, material: row.children[2].value, quantity: Number(row.querySelector('.asn-quantity').value), unit: row.querySelector('.asn-unit').value }));
  $('#asnMessage').textContent = '正在提交…'; try { const created = await api('/api/asns', { method: 'POST', body: JSON.stringify({ portalAsnNumber: form.get('portalAsnNumber'), purchaseOrder: sourcePurchaseOrders.length === 1 ? sourcePurchaseOrders[0] : '', sourcePurchaseOrders, shippingDate: form.get('shippingDate'), plannedDeliveryDate: form.get('plannedDeliveryDate'), transportReference: form.get('transportReference'), items }) }); const sapDelivery = created.sapInboundDelivery || 'SAP 未在响应中返回单号'; $('#asnMessage').textContent = 'ASN 创建成功：Portal 单号 ' + created.portalAsnNumber + '；SAP 内向交货单 ' + sapDelivery + '。需要确认最新状态时，请刷新相关页面。'; $('#asnForm button[type=submit]').disabled = true; selectedOrderLines.clear(); ['dashboard', 'purchaseOrders', 'asns', 'materialDocuments', 'reconciliation'].forEach((key) => sapDataCache.delete(key)); } catch (error) { $('#asnMessage').textContent = `未提交：${error.message}`; }
}
function exportCsv() { if (!records.length) return; const keys = columns[currentRoute] || Object.keys(records[0]); const csv = '\ufeff' + [keys.map((key) => labels[key] || key), ...records.map((record) => keys.map((key) => valueForExport(key, record)))].map((row) => row.map((item) => `"${String(item).replaceAll('"', '""')}"`).join(',')).join('\n'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${resources[currentRoute].title}.csv`; anchor.click(); URL.revokeObjectURL(url); }
function valueForExport(key, record) { if (key === 'MaterialDocumentWithYear') return `${value(record.MaterialDocument)} / ${value(record.MaterialDocumentYear)}`; if (key === 'PurchaseOrderWithItem') return `${value(record.PurchaseOrder)} / ${value(record.PurchaseOrderItem)}`; if (key === 'MaterialWithDescription') return `${value(record.Material)} / ${value(record.MaterialDescription)}`; return value(record[key]); }
function cell(key, raw, record = {}) { if (key === 'MaterialDocumentWithYear') return compoundCell(record.MaterialDocument, `年度 ${value(record.MaterialDocumentYear)} · 项目 ${value(record.MaterialDocumentItem)}`); if (key === 'PurchaseOrderWithItem') return compoundCell(record.PurchaseOrder, `行项目 ${value(record.PurchaseOrderItem)}`); if (key === 'MaterialWithDescription') return compoundCell(record.Material, value(record.MaterialDescription)); if (key === 'OrderType') return orderTypeBadges(raw); const text = fieldValue(key, raw); return /status/i.test(key) ? `<span class="status ${tone(displayStatus(raw))}">${text}</span>` : text; }
function compoundCell(primary, secondary) { return `<b>${escape(value(primary))}</b><small class="sub-cell">${escape(secondary)}</small>`; }
function invoiceReferenceCell(raw) { if (!present(raw)) return '—'; return String(raw).split(',').map((reference) => { const [invoiceNumber, fiscalYear] = reference.trim().split('/'); return `<div class="invoice-reference"><b>${escape(invoiceNumber || '—')}</b><small>年度 ${escape(fiscalYear || '—')}</small></div>`; }).join(''); }
function orderTypeBadges(raw) { return String(raw || '标准订单').split('·').map((type) => `<span class="order-type ${escapeAttr(type.trim())}">${escape(type.trim())}</span>`).join(''); }
function subcontractingComponents(raw) { if (!Array.isArray(raw) || !raw.length) return '—'; return `<ul class="component-list">${raw.map((component) => `<li><b>${escape(component.material || '未提供物料')}</b><span>${escape(component.description || '未提供描述')}</span><small>${escape(component.quantity || '—')} ${escape(component.unit || '')}${component.plant ? ` · 工厂 ${escape(component.plant)}` : ''}</small></li>`).join('')}</ul>`; }
function fieldValue(key, raw) { if (!present(raw)) return '—'; if (key === 'SubcontractingComponents') return subcontractingComponents(raw); if (/Date/.test(key)) return escape(formatDate(raw)); if (/status/i.test(key)) return escape(key === 'SupplierInvoiceStatus' ? displayInvoiceStatus(raw) : displayStatus(raw)); if (key === 'BankAccount' || key === 'IBAN') return escape(maskFinancialIdentifier(raw)); return escape(value(raw)); }
function maskFinancialIdentifier(raw) { const text = String(raw); return text.length <= 4 ? '••••' : `${'•'.repeat(Math.min(12, text.length - 4))}${text.slice(-4)}`; }
function formatDate(raw) { const text = String(raw); const sapV2 = text.match(/^\/Date\((-?\d+)(?:[+-]\d+)?\)\/$/); if (sapV2) { const date = new Date(Number(sapV2[1])); return Number.isNaN(date.getTime()) ? text : date.toISOString().slice(0, 10); } return text.slice(0, 10); }
function documentStatus(route, row) { if (route === 'purchaseOrders') return displayStatus(row.PurchaseOrderStatus); if (route === 'asns') return displayStatus(row.OverallStatus); if (route === 'materialDocuments') return displayStatus(row.ReceiptStatus); return ''; }
function displayStatus(raw) { const text = value(raw); const status = { '01': '待确认', '1': '待确认', '02': '已确认', '2': '已确认', '03': '部分完成', '3': '部分完成', '04': '已完成', '4': '已完成', A: '未处理', B: '部分处理', C: '已完成', X: '已取消', COMPLETED: '已完成', CANCELLED: '已取消', '已收货': '收货', '部分冲销': '部分退回', '部分冲销冲销': '部分退回冲销' }; return status[text.toUpperCase()] || text; }
function displayInvoiceStatus(raw) { const text = value(raw).toUpperCase(); return { A: '预制', B: '预制完成', D: '暂存', '5': '已过账' }[text] || displayStatus(raw); }
function tone(status) { return /逾期|异常|取消/.test(status) ? 'danger' : /待/.test(status) ? 'warning' : /完成|确认|收货|对账/.test(status) ? 'success' : 'info'; }
function present(value) { return value !== null && value !== undefined && value !== ''; } function value(value) { return !present(value) ? '—' : typeof value === 'object' ? JSON.stringify(value) : String(value); } function escape(value) { return String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;'); } function escapeAttr(value) { return escape(value === '—' ? '' : value); }
function initAiAssistant() {
  const floating = $('#aiAssistantFloat'); const launcher = $('#aiAssistantLauncher'); const moveHandle = $('#aiAssistantMove'); const compact = $('#aiAssistantCompact'); const assistant = $('#aiAssistant'); const close = $('#aiAssistantClose'); const form = $('#aiChatForm'); const input = $('#aiChatInput'); const status = $('#aiConnectionState'); const launcherStatus = $('#aiLauncherStatus'); let dragState;
  const setCompact = (enabled) => { floating.classList.toggle('compact', enabled); compact.textContent = enabled ? '+' : '−'; compact.setAttribute('aria-label', enabled ? '还原 AI 助手图标' : '缩小 AI 助手图标'); compact.title = enabled ? '还原图标' : '缩小图标'; try { localStorage.setItem('portal-ai-compact', String(enabled)); } catch { } requestAnimationFrame(() => { if (!floating.style.left) return; const rect = floating.getBoundingClientRect(); applyPosition(rect.left, rect.top, true); }); };
  const boundedPosition = (left, top) => ({ left: Math.min(Math.max(8, left), Math.max(8, window.innerWidth - floating.offsetWidth - 8)), top: Math.min(Math.max(8, top), Math.max(8, window.innerHeight - floating.offsetHeight - 8)) });
  const applyPosition = (left, top, save = false) => { const position = boundedPosition(left, top); floating.style.left = `${position.left}px`; floating.style.top = `${position.top}px`; floating.style.right = 'auto'; floating.style.bottom = 'auto'; if (save) try { localStorage.setItem('portal-ai-position', JSON.stringify({ left: Math.round(position.left), top: Math.round(position.top) })); } catch { } };
  let savedPosition;
  try { setCompact(localStorage.getItem('portal-ai-compact') === 'true'); savedPosition = JSON.parse(localStorage.getItem('portal-ai-position') || 'null'); } catch { }
  requestAnimationFrame(() => { if (savedPosition && Number.isFinite(savedPosition.left) && Number.isFinite(savedPosition.top)) applyPosition(savedPosition.left, savedPosition.top, true); });
  compact.addEventListener('click', () => setCompact(!floating.classList.contains('compact')));
  const finishDrag = (event) => { if (!dragState || event.pointerId !== dragState.pointerId) return; const rect = floating.getBoundingClientRect(); applyPosition(rect.left, rect.top, true); if (moveHandle.hasPointerCapture(event.pointerId)) moveHandle.releasePointerCapture(event.pointerId); dragState = undefined; };
  moveHandle.addEventListener('pointerdown', (event) => { if (event.button !== 0) return; dragState = { pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, left: floating.getBoundingClientRect().left, top: floating.getBoundingClientRect().top }; moveHandle.setPointerCapture(event.pointerId); event.preventDefault(); });
  moveHandle.addEventListener('pointermove', (event) => { if (!dragState || event.pointerId !== dragState.pointerId) return; applyPosition(dragState.left + event.clientX - dragState.startX, dragState.top + event.clientY - dragState.startY); event.preventDefault(); });
  moveHandle.addEventListener('pointerup', finishDrag);
  moveHandle.addEventListener('pointercancel', finishDrag);
  moveHandle.addEventListener('lostpointercapture', () => { dragState = undefined; });
  window.addEventListener('resize', () => { if (!floating.style.left) return; const rect = floating.getBoundingClientRect(); applyPosition(rect.left, rect.top, true); });
  launcher.addEventListener('click', () => { const visible = !assistant.hidden; assistant.hidden = visible; assistant.setAttribute('aria-hidden', String(visible)); if (!visible) input.focus(); }); close.addEventListener('click', () => { assistant.hidden = true; assistant.setAttribute('aria-hidden', 'true'); launcher.focus(); });
  document.querySelectorAll('[data-ai-prompt]').forEach((button) => button.addEventListener('click', () => { input.value = button.dataset.aiPrompt; form.requestSubmit(); }));
  form.addEventListener('submit', sendAiMessage);
  api('/api/agent/status').then((state) => { const ready = state.enabled; status.textContent = ready ? '已连接 DeepSeek AI · 仅当前供应商范围' : (state.issue || 'AI 服务待配置'); launcherStatus.textContent = ready ? 'ONLINE' : '待配置'; launcher.classList.toggle('ai-disabled', !ready); }).catch(() => { status.textContent = 'AI 服务状态读取失败'; launcherStatus.textContent = '异常'; });
}
function appendAiMessage(role, content) {
  const conversation = $('#aiConversation'); const article = document.createElement('article'); article.className = 'ai-message ai-message-' + role; const body = document.createElement('div'); const title = document.createElement('b'); title.textContent = role === 'user' ? '您' : role === 'system' ? '服务提示' : '协同助手'; const text = document.createElement('p'); text.textContent = content; body.append(title, text);
  if (role === 'agent') { const avatar = document.createElement('span'); avatar.className = 'ai-avatar'; avatar.textContent = '✦'; article.append(avatar); } article.append(body); conversation.append(article); conversation.scrollTop = conversation.scrollHeight; return article;
}
function appendAiTools(tools) { if (!tools?.length) return; const trace = document.createElement('div'); trace.className = 'ai-tool-trace'; trace.textContent = '已调用：'; tools.forEach((tool) => { const item = document.createElement('span'); item.textContent = tool.name + ' · ' + tool.summary; trace.append(item); }); $('#aiConversation').append(trace); $('#aiConversation').scrollTop = $('#aiConversation').scrollHeight; }
async function sendAiMessage(event) {
  event.preventDefault(); const input = $('#aiChatInput'); const question = input.value.trim(); if (!question) return; const send = $('#aiChatSend'); appendAiMessage('user', question); aiHistory.push({ role: 'user', content: question }); input.value = ''; send.disabled = true; send.textContent = '查询中…'; const pending = appendAiMessage('system', '正在判断协同任务并校验当前供应商范围…');
  try { const result = await api('/api/agent/chat', { method: 'POST', body: JSON.stringify({ message: question, history: aiHistory.slice(-8) }) }); pending.remove(); appendAiMessage('agent', result.content || '未返回可用回答。'); appendAiTools(result.tools); aiHistory.push({ role: 'assistant', content: result.content || '' }); } catch (error) { pending.remove(); appendAiMessage('system', '暂时无法完成：' + error.message); } finally { send.disabled = false; send.innerHTML = '发送 <span>↗</span>'; input.focus(); }
}
async function readSapData(key, url, force = false) { if (!force && sapDataCache.has(key)) return { payload: sapDataCache.get(key), cached: true }; const payload = await api(url); sapDataCache.set(key, payload); return { payload, cached: false }; }
async function api(url, options = {}) { const response = await fetch(url, { ...options, headers: { accept: 'application/json', ...(options.body ? { 'content-type': 'application/json' } : {}), ...(options.headers || {}) } }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.message || `请求失败（${response.status}）`); return payload; }
boot();
